import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.Cm6XCzck.js";const p=JSON.parse('{"title":"Host Verification, Executor Identity, and Enterprise Execution: Evidence","description":"","frontmatter":{"title":"Host Verification, Executor Identity, and Enterprise Execution: Evidence","date":"2026-09-03","language":"en"},"headers":[],"relativePath":"en/research/evidence/2026-09-03-host-authority-conformance.md","filePath":"en/research/evidence/2026-09-03-host-authority-conformance.md","lastUpdated":1788456864000}'),n={name:"en/research/evidence/2026-09-03-host-authority-conformance.md"};function s(i,e,l,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="host-verification-executor-identity-and-enterprise-execution-public-evidence-guide" tabindex="-1">Host Verification, Executor Identity, and Enterprise Execution: Public Evidence Guide <a class="header-anchor" href="#host-verification-executor-identity-and-enterprise-execution-public-evidence-guide" aria-label="Permalink to &quot;Host Verification, Executor Identity, and Enterprise Execution: Public Evidence Guide&quot;">​</a></h1><p><a href="/joinwell52/zh/research/evidence/2026-09-03-host-authority-conformance">简体中文</a></p><p>This package supports three articles dated September 3, 2026. The first two are controlled studies on a fixed baseline; the third is a product outlook grounded in official sources. <strong>No remediation was implemented in this study. This is not independent QA or release acceptance.</strong></p><h2 id="baseline-and-method" tabindex="-1">Baseline and method <a class="header-anchor" href="#baseline-and-method" aria-label="Permalink to &quot;Baseline and method&quot;">​</a></h2><p>CodeFlowMu is our local multi-Agent collaboration system. The tested product was <strong>V2.2.6</strong>, commit <code>5c94d8c3b0147b779b17f620b811c6a17cc65288</code>, on Windows x64 with Node v24.16.0. The original before/after records have identical commits and empty worktree status. Publishing these articles did not modify product code.</p><p>E1 injected controlled results through existing registry, staging, and probe seams while using the real <code>HostAdmissionControlPlaneService.runTests</code> and persistence boundary. It did not launch real providers, install packages, approve synchronization, adopt Host updates, or start an SDK. Cursor/Codex are fixture Host labels—not evidence of defects in those products.</p><p>E2 used real OperationApproval prepare/approve, controlled durable records, a new service instance&#39;s get path, real OS process queries, and the existing writer-lock function. The year-2000 timestamp is synthetic. The study did not induce real OS PID reuse or restart the Runtime. <strong>External executor calls: zero.</strong></p><h2 id="claim-→-observation-→-limit" tabindex="-1">Claim → observation → limit <a class="header-anchor" href="#claim-→-observation-→-limit" aria-label="Permalink to &quot;Claim → observation → limit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim</th><th>Supporting data</th><th>What it supports—and does not</th></tr></thead><tbody><tr><td>Empty results can still become VERIFIED</td><td>E1 empty; 2 Hosts × 2 rounds; progress 0/4</td><td>Real service aggregation accepts an empty list; not evidence that a real provider failed to run</td></tr><tr><td>Incomplete, duplicate, and out-of-plan results also pass</td><td>E1 partial/duplicate/unknown-id plus empty; 16 counterexamples among 32 observations</td><td>Missing plan-completeness checks; not a production failure rate or successful authorization bypass</td></tr><tr><td>Full, BLOCKED, FAIL, and thrown-error controls behave as recorded</td><td>E1 full/blocked/failed/throws; 16 controls</td><td>Existing protections remain; the ADMIN synchronization gate still follows VERIFIED</td></tr><tr><td>The same live PID need not be the original executor</td><td>E2 reused-pid-fixture; executing in both rounds while the legacy writer-lock comparison detects stale</td><td>Synthetic old timestamp versus actual OS creation time; identity mismatch proves neither effect absence nor permission to retry</td></tr><tr><td>Existing regressions still pass</td><td>7 groups × 2 rounds; 41 pass / 0 fail / 0 skip per round</td><td>Not 82 independent tests, nor evidence that the reported gaps were repaired</td></tr><tr><td>Enterprise execution can remain separate from cloud control</td><td>Official Cursor sources S4–S7</td><td>Product boundaries and conditional forecasts; no deployment, cost, recovery-rate, or market benchmark</td></tr></tbody></table><p>The export preserves original row order, outcomes, states, rounds, timestamps, and counters. It removes absolute local paths, temporary directories, synthetic run/candidate IDs, execution commands, and full logs. OS process tokens are omitted while creation-time milliseconds remain available for the temporal comparison.</p><h2 id="downloads-and-read-only-verification" tabindex="-1">Downloads and read-only verification <a class="header-anchor" href="#downloads-and-read-only-verification" aria-label="Permalink to &quot;Downloads and read-only verification&quot;">​</a></h2><p>Save these files together and run <code>node check.mjs</code>. No dependencies are required. The checker does not access the network, write files, or launch a product or Agent.</p><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/observations-e1.json" target="_blank" rel="noreferrer">E1: all 32 observations</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/observations-e2.json" target="_blank" rel="noreferrer">E2: all 6 observations</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/regressions.json" target="_blank" rel="noreferrer">Two rounds of seven regression groups</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/sources.json" target="_blank" rel="noreferrer">External sources and fixed commits</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/provenance.json" target="_blank" rel="noreferrer">Projection rules and original-file SHA-256 hashes</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/check.mjs" target="_blank" rel="noreferrer">Read-only check.mjs</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/manifest.json" target="_blank" rel="noreferrer">Public-file SHA-256 manifest</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/README.en.md" target="_blank" rel="noreferrer">English README</a> / <a href="https://joinwell52-ai.github.io/joinwell52/assets/evidence/2026-09-03-host-authority-conformance/README.zh.md" target="_blank" rel="noreferrer">中文 README</a></li></ul><p>Expected results:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E1: 32 observations / 16 counterexamples</span></span>
<span class="line"><span>E2: 6 observations / 0 executor calls</span></span>
<span class="line"><span>Regression round 1: 41 pass / 0 fail / 0 skip</span></span>
<span class="line"><span>Regression round 2: 41 pass / 0 fail / 0 skip</span></span></code></pre></div><p>The checker verifies scenario coverage, controls, per-round counts, states, the temporal contradiction, and file hashes. <strong>It is not a public product reproducer for the original experiments.</strong> Product source and full internal probes remain access-restricted; this package cannot independently establish the behavior of that restricted source. Hashes establish consistency relative to the manifest, not the truth or authenticity of an observation, and are not digital signatures. Readers can check whether the author&#39;s exported observations support the published numbers. Full product reproduction requires authorized access to the same baseline and internal probes.</p><h2 id="external-sources-and-background" tabindex="-1">External sources and background <a class="header-anchor" href="#external-sources-and-background" aria-label="Permalink to &quot;External sources and background&quot;">​</a></h2><ul><li><a href="https://github.com/OpenHands/software-agent-sdk/pull/4834" target="_blank" rel="noreferrer">OpenHands software-agent-sdk #4834</a>: the software-development Agent SDK from OpenHands. The change exercises real-provider configuration construction without inference. It is not a CodeFlowMu completeness fix and should not be represented as coverage in every default CI job.</li><li><a href="https://github.com/openai/codex/pull/42381" target="_blank" rel="noreferrer">OpenAI Codex #42381</a> and <a href="https://github.com/openai/codex/pull/42392" target="_blank" rel="noreferrer">#42392</a>: Codex is OpenAI&#39;s coding Agent. The changes provide external engineering comparisons for Windows process identity and successor readiness/handoff. They do not establish equivalent CodeFlowMu capabilities.</li><li><a href="https://cursor.com/changelog/self-hosted-machines" target="_blank" rel="noreferrer">Cursor announcement</a>, <a href="https://cursor.com/docs/cloud-agent/self-hosted" target="_blank" rel="noreferrer">Self-Hosted Machines</a>, <a href="https://cursor.com/docs/cloud-agent/self-hosted/pool" target="_blank" rel="noreferrer">Team Pools</a>, and <a href="https://cursor.com/docs/cloud-agent/self-hosted/computer-use" target="_blank" rel="noreferrer">Computer use</a>: Cursor is Anysphere&#39;s AI coding product. The September 2 update and documentation checked through September 3 support a cloud loop, enterprise workers, conditional workspace recovery, and human takeover—not “no outbound data” or a completely private Agent deployment.</li></ul><p>Web documentation can change. The study cutoff is September 3, 2026; fixed PR merge SHAs are recorded in sources.json. This package does not republish third-party full text.</p><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ol><li><a href="/joinwell52/en/engineering/2026-09-03-empty-test-results-verified">The Test Results Are Empty. Why Does the System Still Say “Verified”?</a></li><li><a href="/joinwell52/en/engineering/2026-09-03-process-alive-owner-identity">The Process Is Alive. Is It Still the Original Executor?</a></li><li><a href="/joinwell52/en/digital-employee/2026-09-03-cursor-self-hosted-agent-outlook">When Agents Enter the Enterprise Network: What Do Cursor Self-Hosted Machines Change?</a></li></ol>`,21)])])}const f=t(n,[["render",s]]);export{p as __pageData,f as default};
